1	import { NgTemplateOutlet } from '@angular/common';
2	import { ChangeDetectionStrategy, Component, computed, effect, inject, input } from '@angular/core';
3	import { HlmSheetImports } from '@spartan-ng/helm/sheet';
4	import { classes, hlm } from '@spartan-ng/helm/utils';
5	import type { ClassValue } from 'clsx';
6	import { HlmSidebarService, type SidebarVariant } from './hlm-sidebar.service';
7	import { injectHlmSidebarConfig } from './hlm-sidebar.token';
8	
9	@Component({
10	  selector: 'hlm-sidebar',
11	  imports: [NgTemplateOutlet, HlmSheetImports],
12	  changeDetection: ChangeDetectionStrategy.OnPush,
13	  host: {
14	    '[attr.data-slot]': '_dataSlot()',
15	    '[attr.data-state]': '_dataState()',
16	    '[attr.data-collapsible]': '_dataCollapsible()',
17	    '[attr.data-variant]': '_dataVariant()',
18	    '[attr.data-side]': '_dataSide()',
19	  },
20	  template: `
21	    <ng-template #contentContainer>
22	      <ng-content />
23	    </ng-template>
24	
25	    @if (collapsible() === 'none') {
26	      <ng-container *ngTemplateOutlet="contentContainer"></ng-container>
27	    } @else if (_sidebarService.isMobile()) {
28	      <hlm-sheet
29	        [side]="side()"
30	        [state]="_sidebarService.openMobile() ? 'open' : 'closed'"
31	        (stateChanged)="_sidebarService.setOpenMobile($event === 'open')"
32	      >
33	        <hlm-sheet-content
34	          *hlmSheetPortal="let ctx"
35	          data-slot="sidebar"
36	          data-sidebar="sidebar"
37	          data-mobile="true"
38	          class="bg-sidebar text-sidebar-foreground h-svh w-(--sidebar-width) p-0 [&>button]:hidden"
39	          [style.--sidebar-width]="sidebarWidthMobile()"
40	        >
41	          <div class="flex h-full w-full flex-col">
42	            <ng-container *ngTemplateOutlet="contentContainer" />
43	          </div>
44	        </hlm-sheet-content>
45	      </hlm-sheet>
46	    } @else {
47	      <!-- Sidebar gap on desktop -->
48	      <div data-slot="sidebar-gap" [class]="_sidebarGapComputedClass()"></div>
49	      <div
50	        data-slot="sidebar-container"
51	        [attr.data-side]="_dataSide()"
52	        [class]="_sidebarContainerComputedClass()"
53	      >
54	        <div
55	          data-sidebar="sidebar"
56	          data-slot="sidebar-inner"
57	          class="bg-sidebar group-data-[variant=floating]:ring-sidebar-border group-data-[variant=floating]:rounded-lg group-data-[variant=floating]:shadow-sm group-data-[variant=floating]:ring-1 flex size-full flex-col"
58	        >
59	          <ng-container *ngTemplateOutlet="contentContainer" />
60	        </div>
61	      </div>
62	    }
63	  `,
64	})
65	export class HlmSidebar {
66	  protected readonly _sidebarService = inject(HlmSidebarService);
67	  private readonly _config = injectHlmSidebarConfig();
68	  public readonly sidebarWidthMobile = input<string>(this._config.sidebarWidthMobile);
69	
70	  public readonly side = input<'left' | 'right'>('left');
71	  public readonly variant = input<SidebarVariant>(this._sidebarService.variant());
72	  public readonly collapsible = input<'offcanvas' | 'icon' | 'none'>('offcanvas');
73	
74	  protected readonly _sidebarGapComputedClass = computed(() =>
75	    hlm(
76	      'transition-[width] duration-200 ease-linear relative w-(--sidebar-width) bg-transparent',
77	      'group-data-[collapsible=offcanvas]:w-0',
78	      'group-data-[side=right]:rotate-180',
79	      this.variant() === 'floating' || this.variant() === 'inset'
80	        ? 'group-data-[collapsible=icon]:w-[calc(var(--sidebar-width-icon)+(--spacing(4)))]'
81	        : 'group-data-[collapsible=icon]:w-(--sidebar-width-icon)',
82	    ),
83	  );
84	
85	  public readonly sidebarContainerClass = input<ClassValue>('');
86	  protected readonly _sidebarContainerComputedClass = computed(() =>
87	    hlm(
88	      'fixed inset-y-0 z-10 hidden h-svh w-(--sidebar-width) transition-[left,right,width] duration-200 ease-linear data-[side=left]:left-0 data-[side=left]:group-data-[collapsible=offcanvas]:left-[calc(var(--sidebar-width)*-1)] data-[side=right]:right-0 data-[side=right]:group-data-[collapsible=offcanvas]:right-[calc(var(--sidebar-width)*-1)] md:flex',
89	      this.variant() === 'floating' || this.variant() === 'inset'
90	        ? 'p-2 group-data-[collapsible=icon]:w-[calc(var(--sidebar-width-icon)+(--spacing(4))+2px)]'
91	        : 'group-data-[collapsible=icon]:w-(--sidebar-width-icon) group-data-[side=left]:border-r group-data-[side=right]:border-l',
92	      this.sidebarContainerClass(),
93	    ),
94	  );
95	
96	  protected readonly _dataSlot = computed(() => {
97	    return !this._sidebarService.isMobile() ? 'sidebar' : undefined;
98	  });
99	
100	  private readonly _collapsibleAndNonMobile = computed(() => {
101	    return this.collapsible() !== 'none' && !this._sidebarService.isMobile();
102	  });
103	
104	  protected readonly _dataState = computed(() => {
105	    return this._collapsibleAndNonMobile() ? this._sidebarService.state() : undefined;
106	  });
107	
108	  protected readonly _dataCollapsible = computed(() => {
109	    if (this._collapsibleAndNonMobile()) {
110	      return this._sidebarService.state() === 'collapsed' ? this.collapsible() : '';
111	    }
112	    return undefined;
113	  });
114	
115	  protected readonly _dataVariant = computed(() => {
116	    return this._collapsibleAndNonMobile() ? this.variant() : undefined;
117	  });
118	
119	  protected readonly _dataSide = computed(() => {
120	    return this._collapsibleAndNonMobile() ? this.side() : undefined;
121	  });
122	
123	  constructor() {
124	    // Sync variant input with service
125	    effect(() => {
126	      this._sidebarService.setVariant(this.variant());
127	    });
128	
129	    classes(() => {
130	      if (this.collapsible() === 'none') {
131	        return hlm('bg-sidebar text-sidebar-foreground flex h-svh w-(--sidebar-width) flex-col');
132	      } else if (this._sidebarService.isMobile()) {
133	        return '';
134	      } else {
135	        return hlm('group peer text-sidebar-foreground hidden md:block');
136	      }
137	    });
138	  }
139	}
140

