32	  public readonly openMobile: Signal<boolean> = this._openMobile.asReadonly();
33	  public readonly isMobile: Signal<boolean> = this._isMobile.asReadonly();
34	  public readonly variant: Signal<SidebarVariant> = this._variant.asReadonly();
35	
