@reference "../styles.css";

/* Let the inset region shrink below its content so a wide child cannot push the page sideways. */
main {
  @apply min-w-0;
}

.app-brand {
  @apply flex min-w-0 items-center gap-2 px-2 py-1 font-semibold text-sidebar-foreground;
}

.app-brand__name {
  @apply truncate;
}

.app-account {
  @apply flex min-w-0 items-center gap-3 px-2 py-1;
}

.app-account__text {
  @apply flex min-w-0 flex-col text-sm text-sidebar-foreground;
}

.app-account__meta {
  @apply truncate text-xs text-sidebar-muted;
}

.app-topbar {
  @apply flex flex-wrap items-center gap-3 border-b border-border bg-background px-4 py-3;
}

.app-topbar__leading {
  @apply flex min-w-0 flex-1 items-center gap-2;
}

.app-topbar__search {
  @apply w-full sm:w-72;
}

.app-topbar__controls {
  @apply ms-auto flex items-center gap-1;
