/* You can add global styles to this file, and also import other style files */

/*
 * Hero Ops Console palette. Each role from the capstone build spec is mapped onto
 * spartan's own token; the semantic and rail roles without a spartan token get a
 * named custom property and are exposed to Tailwind below.
 */
@theme inline {
  --color-success: var(--success);
  --color-warning: var(--warning);
  --color-info: var(--info);
  --color-sidebar-muted: var(--sidebar-muted);
}

:root {
  color-scheme: light;

  --font-sans:
    -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, 'Helvetica Neue', Arial, 'Noto Sans',
    sans-serif, 'Apple Color Emoji', 'Segoe UI Emoji', 'Segoe UI Symbol', 'Noto Color Emoji';

  --chart-1: oklch(0.646 0.222 41.116);
  --chart-2: oklch(0.6 0.118 184.704);
  --chart-3: oklch(0.398 0.07 227.392);
  --chart-4: oklch(0.828 0.189 84.429);
  --chart-5: oklch(0.769 0.188 70.08);
  --radius: 0.625rem;

  /* page and surfaces */
  --background: #f6f7fa;
  --foreground: #1b1e2b;
  --card: #ffffff;
  --card-foreground: #1b1e2b;
  --popover: #ffffff;
  --popover-foreground: #1b1e2b;
  --muted: #eef0f6;
  --muted-foreground: #5b6072;
  --border: #e4e7ef;
  --input: #e4e7ef;

  /* action: amber-gold. Accent is the subtle hover surface, a different role. */
  --primary: #d8891a;
  /* The spec's #ffffff measures 2.8:1 on this amber; the dark ink measures 6.1:1. */
  --primary-foreground: #241a05;
  --secondary: #eef0f6;
  --secondary-foreground: #1b1e2b;
  --accent: #eef0f6;
  --accent-foreground: #1b1e2b;
  /* Solid, not 35% alpha: the translucent amber measures 1.4:1 on white. */
  --ring: #b8741a;
  --destructive: #e5484d;

  /* semantic: carry meaning, kept separate from the accent */
  --success: #2fb574;
  --warning: #e4802b;
  --info: #4f7cf0;

  /* navigation rail: dark in both themes */
  --sidebar: #1e2233;
  --sidebar-foreground: #eceef6;
  --sidebar-muted: #9aa0b4;
  --sidebar-primary: #d8891a;
  --sidebar-primary-foreground: #241a05;
  --sidebar-accent: #2a2f45;
  --sidebar-accent-foreground: #eceef6;
  --sidebar-border: #2a2f45;
  --sidebar-ring: #f5b843;
}

:root.dark {
  color-scheme: dark;

  --chart-1: oklch(0.488 0.243 264.376);
  --chart-2: oklch(0.696 0.17 162.48);
  --chart-3: oklch(0.769 0.188 70.08);
  --chart-4: oklch(0.627 0.265 303.9);
  --chart-5: oklch(0.645 0.246 16.439);

  /* page and surfaces */
  --background: #0e1018;
  --foreground: #eceef6;
  --card: #171a26;
  --card-foreground: #eceef6;
  --popover: #171a26;
  --popover-foreground: #eceef6;
  --muted: #1e2231;
  --muted-foreground: #9aa0b4;
  --border: #272b3b;
  --input: #272b3b;

  /* action: amber-gold */
  --primary: #f5b843;
  --primary-foreground: #241a05;
  --secondary: #1e2231;
  --secondary-foreground: #eceef6;
  --accent: #1e2231;
  --accent-foreground: #eceef6;
  --ring: rgb(245 184 67 / 40%);
  --destructive: #f2585d;

  /* semantic */
  --success: #3ecb84;
  --warning: #f0983f;
  --info: #6f97f6;

  /* navigation rail: dark in both themes */
  --sidebar: #10121c;
  --sidebar-foreground: #eceef6;
  --sidebar-muted: #8b90a6;
  --sidebar-primary: #f5b843;
  --sidebar-primary-foreground: #241a05;
  --sidebar-accent: #20263c;
  --sidebar-accent-foreground: #eceef6;
  --sidebar-border: #20263c;
  --sidebar-ring: rgb(245 184 67 / 40%);
}

@layer base {
  * {
    @apply border-border outline-ring/50;
  }
  body {
    @apply bg-background text-foreground;
  }
}

